('webservices.rest.quietDocs','true','If the value of this setting is \"true\", then nothing is logged while the Swagger specification is being generated.','94d45b4d-268f-455a-8696-4b85fb39a86b',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('webservices.rest.started','true','DO NOT MODIFY. true/false whether or not the webservices.rest module has been started.  This is used to make sure modules that were running  prior to a restart are started again','5a4469cc-bd30-4cc6-9538-e0b8068620d2',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('webservices.rest.uriPrefix',NULL,'The URI prefix through which clients consuming web services will connect to the web application, should be of the form http://{ipAddress}:{port}/{contextPath}','bb4a0dd7-996e-409d-8d40-beee03990282',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
